# Code Generated by Sidekick is for learning and experimentation purposes only.
Write-Host "`n=== COMPLETE SYSTEM TEST ===" -ForegroundColor Green
Write-Host ("="*70) -ForegroundColor Green

# Test 1: Create Short URLsssss
Write-Host "`n[1/5] Testing URL Creation..." -ForegroundColor Cyan
$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$body = @{
    url = "https://www.example.com/test-$timestamp"
    created_by = "system-test"
} | ConvertTo-Json

try {
    $response = Invoke-RestMethod -Uri "http://localhost:5001/shorten" -Method POST -ContentType "application/json" -Body $body
    $shortCode = $response.short_url.Split('/')[-1]
    Write-Host "    [OK] Created short URL: $shortCode" -ForegroundColor Green
    Write-Host "    Full URL: $($response.short_url)" -ForegroundColor White
} catch {
    Write-Host "    [FAIL] Could not create URL: $($_.Exception.Message)" -ForegroundColor Red
    exit 1
}

# Test 2: Verify on Primary
Write-Host "`n[2/5] Verifying data on PRIMARY..." -ForegroundColor Cyan
$primaryCheck = docker exec postgres-primary psql -U admin -d urlshortener -t -c "SELECT url FROM urls WHERE short_url='$shortCode';"
if ($primaryCheck.Trim()) {
    Write-Host "    [OK] Found on primary: $($primaryCheck.Trim())" -ForegroundColor Green
} else {
    Write-Host "    [FAIL] Not found on primary!" -ForegroundColor Red
}

# Test 3: Wait and check replica
Write-Host "`n[3/5] Checking REPLICA synchronization..." -ForegroundColor Cyan
Start-Sleep -Seconds 3
$replicaCheck = docker exec postgres-replica psql -U admin -d urlshortener -t -c "SELECT url FROM urls WHERE short_url='$shortCode';"
if ($replicaCheck.Trim()) {
    Write-Host "    [OK] Replicated to standby: $($replicaCheck.Trim())" -ForegroundColor Green
} else {
    Write-Host "    [WARN] Not yet on replica (replication lag)" -ForegroundColor Yellow
}

# Test 4: Test Redirect
Write-Host "`n[4/5] Testing URL redirect..." -ForegroundColor Cyan
try {
    $redirectResult = Invoke-WebRequest -Uri "http://localhost:5002/$shortCode" -MaximumRedirection 0 -UseBasicParsing -ErrorAction Stop
    Write-Host "    [INFO] Response status: $($redirectResult.StatusCode)" -ForegroundColor White

    if ($redirectResult.StatusCode -eq 200) {
        Write-Host "    [WARN] Got 200 instead of redirect (check redirect-service config)" -ForegroundColor Yellow
    }
} catch {
    $statusCode = $_.Exception.Response.StatusCode.value__
    if ($statusCode -in @(301, 302, 307, 308)) {
        $location = $_.Exception.Response.Headers.Location
        Write-Host "    [OK] Redirect working! (HTTP $statusCode)" -ForegroundColor Green
        Write-Host "    Redirects to: $location" -ForegroundColor White
    } elseif ($statusCode -eq 404) {
        Write-Host "    [FAIL] URL not found (404) - replica may not be ready" -ForegroundColor Red
    } else {
        Write-Host "    [WARN] Unexpected status: $statusCode" -ForegroundColor Yellow
    }
}

# Test 5: Check Analytics
Write-Host "`n[5/5] Checking analytics..." -ForegroundColor Cyan

# FIXED: Query click_events instead of clicks
$tableCheck = docker exec postgres-primary psql -U admin -d urlshortener -t -c "SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'click_events');"
if ($tableCheck -match "t") {
    Write-Host "    [OK] click_events table exists" -ForegroundColor Green

    Start-Sleep -Seconds 3
    $clickCount = docker exec postgres-primary psql -U admin -d urlshortener -t -c "SELECT COUNT(*) FROM click_events WHERE short_url='$shortCode';" 2>&1

    if ($clickCount -match "^\s*\d+\s*$") {
        $clickCountValue = [int]$clickCount.Trim()
        if ($clickCountValue -gt 0) {
            Write-Host "    [OK] Click event recorded! ($clickCountValue clicks)" -ForegroundColor Green

            # Show the actual event details
            Write-Host "`n    Recent click details:" -ForegroundColor White
            docker exec postgres-primary psql -U admin -d urlshortener -c "SELECT short_url, clicked_at, ip_address, user_agent FROM click_events WHERE short_url='$shortCode' ORDER BY clicked_at DESC LIMIT 3;"
        } else {
            Write-Host "    [INFO] No clicks yet (analytics may still be processing)" -ForegroundColor White
        }
    } else {
        Write-Host "    [WARN] Could not query click_events: $clickCount" -ForegroundColor Yellow
    }
} else {
    Write-Host "    [FAIL] click_events table does not exist!" -ForegroundColor Red
}

# Summary
Write-Host "`n" + ("="*70) -ForegroundColor Green
Write-Host "=== TEST COMPLETE ===" -ForegroundColor Green
Write-Host ("="*70) -ForegroundColor Green

Write-Host "`n--- Service Endpoints ---" -ForegroundColor Cyan
Write-Host "  Create URL: POST http://localhost:5001/shorten" -ForegroundColor White
Write-Host "  Redirect:   GET  http://localhost:5002/{shortcode}" -ForegroundColor White
Write-Host "  Analytics:  GET  http://localhost:5002/analytics/{shortcode}" -ForegroundColor White
Write-Host "  RabbitMQ:   http://localhost:15672 (guest/guest)" -ForegroundColor White

Write-Host "`n--- Database Info ---" -ForegroundColor Cyan
Write-Host "  Primary:  localhost:5432 (read/write)" -ForegroundColor White
Write-Host "  Replica:  localhost:5433 (read-only)" -ForegroundColor White

Write-Host "`n--- Current Data ---" -ForegroundColor Cyan
docker exec postgres-primary psql -U admin -d urlshortener -c "
SELECT
    'urls' as table_name,
    COUNT(*) as total_rows
FROM urls
UNION ALL
SELECT
    'click_events' as table_name,
    COUNT(*) as total_rows
FROM click_events;
"

Write-Host "`n--- Service Status ---" -ForegroundColor Cyan
docker compose ps
